const $=s=>document.querySelector(s);
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storageOK=true;function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}function persist(key,v){try{localStorage.setItem(key,JSON.stringify(v));return true}catch{storageOK=false;toast('浏览器存储不可用，请导出项目备份。');return false}}
let animationTimer=null;function stopAnimation(){clearInterval(animationTimer);animationTimer=null}
let progress=read('academy-progress-v1',{}),projects=read('academy-projects-v1',[]),page='home',chapter=0,current=null,phase=0,decision=null,labMode=false;
const robot=`<svg viewBox="0 0 220 245" role="img" aria-label="等待你训练的机器人"><ellipse cx="110" cy="224" rx="65" ry="10" fill="#9dbb7933"/><path d="M110 34V19" stroke="#50734c" stroke-width="5"/><circle cx="110" cy="15" r="8" fill="#dd996b"/><rect x="45" y="37" width="130" height="103" rx="35" fill="#fdfdf5" stroke="#577551" stroke-width="3"/><rect x="56" y="53" width="108" height="65" rx="24" fill="#244b3e"/><rect x="75" y="72" width="13" height="24" rx="6" fill="#d4f7a7"/><rect x="132" y="72" width="13" height="24" rx="6" fill="#d4f7a7"/><path d="M99 101 Q110 109 121 101" fill="none" stroke="#d4f7a7" stroke-width="3"/><rect x="39" y="72" width="8" height="31" rx="4" fill="#789366"/><rect x="173" y="72" width="8" height="31" rx="4" fill="#789366"/><rect x="65" y="143" width="90" height="59" rx="20" fill="#d2e8b4" stroke="#577551" stroke-width="3"/><circle cx="110" cy="171" r="12" fill="#78995b"/><path d="M104 172l4 4 9-10" fill="none" stroke="#e6f4d5" stroke-width="3"/><path d="M63 155Q36 154 39 180M156 155q28-14 28-32" fill="none" stroke="#789366" stroke-width="13" stroke-linecap="round"/><rect x="77" y="198" width="21" height="22" rx="7" fill="#789366"/><rect x="124" y="198" width="21" height="22" rx="7" fill="#789366"/></svg>`;
function count(){return Object.keys(progress).length}function toast(t){$('.toast')?.remove();let e=document.createElement('div');e.className='toast';e.textContent=t;document.body.append(e);setTimeout(()=>e.remove(),4000)}
function shell(content,active='home'){document.getElementById('app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brandmark">✳</span><div>AI Academy<small>训练师学院</small></div></div><nav class="nav" aria-label="主导航"><button class="${active==='home'?'active':''}" onclick="navigate('home')"><i>◈</i>冒险地图</button><button class="${active==='lab'?'active':''}" onclick="navigate('lab')"><i>⚗</i>自由实验室</button><button class="${active==='robot'?'active':''}" onclick="navigate('robot')"><i>▣</i>我的机器人</button></nav><div class="sidefoot"><strong>每次尝试，都在进化。</strong><p>观察 · 实验 · 训练 · 理解</p><div class="progress"><span style="width:${count()/30*100}%"></span></div><p style="margin:9px 0 0">已完成 ${count()} / 30 关</p></div></aside><main class="main"><header class="topbar"><span class="crumb">训练师学院 <span style="color:#b0b5a8"> / </span> ${active==='lab'?'自由实验室':active==='robot'?'成长档案':'学习冒险'}</span><div class="row"><span class="pill">✦ ${count()} 项挑战完成</span><span class="avatar">T</span></div></header>${content}<div class="footer">AI ACADEMY · LEARN AI BY TRAINING AI<br>进度与作品保存在此浏览器，建议定期导出。教学版 v0.3 · 从实验到应用</div></main></div>`}
function navigate(p){stopAnimation();page=p;current=null;if(p==='home')home();else if(p==='lab')lab();else inventory();window.scrollTo(0,0)}
function home(){let next=LEVELS.find(l=>!progress[l.id])||LEVELS[29];shell(`<section class="hero"><div class="herotext"><div class="eyebrow">YOUR AI ADVENTURE STARTS HERE</div><h1>亲手把一个 AI<br>教聪明<span class="spark">。</span></h1><p>它还不懂这个世界。<br>用你的每一次实验，解锁它的新能力。</p><button class="primary" onclick="openLevel(${next.id})">${count()?'继续冒险':'开启第一关'} <span>↗</span></button></div><div class="robot-stage"><div class="orbit"></div>${robot}<div class="bubble one">数据 → 发现规律</div><div class="bubble two">你好，训练师！✧</div></div></section><div class="sectionhead"><h2>你的学习地图</h2><small>6 个章节 · 30 次发现</small></div><div class="chapters">${CHAPTERS.map((c,i)=>`<button class="chapter ${chapter===i?'selected':''}" onclick="chooseChapter(${i})">${c[0]} ${c[1]}</button>`).join('')}</div><div class="row between" style="margin:10px 0 16px"><small>${CHAPTERS[chapter][2]}</small><small>${LEVELS.filter(l=>l.chapter===chapter&&progress[l.id]).length} / 5 完成</small></div><div class="levelgrid">${LEVELS.filter(l=>l.chapter===chapter).map(l=>`<button class="card level ${progress[l.id]?'complete':''}" onclick="openLevel(${l.id})"><div class="row between"><div class="iconbox">${CHAPTERS[l.chapter][3]}</div><span class="number">${progress[l.id]?'✓ 已完成':'LEVEL '+String(l.id).padStart(2,'0')}</span></div><h3>${esc(l.title)}</h3><p>${l.desc}</p><div class="levelmeta"><span>${l.title.includes('BOSS')?'⚔ 综合挑战':'互动实验'}</span><span>开始探索 ↗</span></div></button>`).join('')}</div><div class="introstrip"><span style="font-size:26px">⚗</span><div><strong>有自己的想法？去自由实验室试试看。</strong><p class="muted">自由画数据、训练网络，或教机器人走出迷宫。</p></div><button aria-label="打开自由实验室" onclick="navigate('lab')">↗</button></div>`)}
function chooseChapter(i){chapter=i;home()}
const LABS=[['knn','自由分类画布','自己画数据，观察邻居和分类边界。','◌'],['reg','预测工作室','调整参数，观察误差与真实梯度下降。','⌁'],['nn','神经网络实验室','修改网络结构，训练非线性分类器。','✳'],['vision','手绘图像识别器','收集像素样本，训练自己的图像分类器。','▧'],['rl','迷宫训练场','修改地图和奖励，训练 Q-learning 策略。','⌘'],['go','5×5 围棋实验','训练一步提子评分器，与模型交换落子。','●'],['agent','模拟电脑智能体','用试错学习完成一个桌面任务。','▣']];
function lab(){shell(`<div class="pagehead"><div class="eyebrow">A PLAYGROUND FOR YOUR IDEAS</div><h1>欢迎来到自由实验室<span class="spark">。</span></h1><p>没有标准答案。提出一个想法，改变一个变量，看看你的 AI 会发生什么。</p></div><div class="labgrid">${LABS.map(([type,title,desc,icon])=>`<button class="card labcard" onclick="openLab('${type}')"><div class="row between"><span class="iconbox">${icon}</span><span class="tag">${['go','agent'].includes(type)?'教学沙盒':'真实本地计算'} ↗</span></div><h3>${title}</h3><p>${desc}</p></button>`).join('')}</div><div class="sectionhead"><h2>我的实验项目</h2><button class="secondary" onclick="importProject()">导入 JSON</button></div><div class="levelgrid">${projects.length?projects.map((p,i)=>`<div class="card"><h3>${esc(p.name)}</h3><p class="muted">${esc(p.date)} · ${esc(p.engine)}</p><div class="row"><button class="secondary" onclick="loadProject(${i})">继续实验</button><button onclick="exportProject(${i})">导出 ↓</button></div></div>`).join(''):'<div class="empty">打开一个实验，点击“保存作品”后会出现在这里。</div>'}</div>`,'lab')}
function openLab(type){stopAnimation();let source=LEVELS.find(l=>l.engine===type&&(['final','own','q','go','agent','draw'].includes(l.variant)))||LEVELS.find(l=>l.engine===type);current={...source,id:0,title:LABS.find(a=>a[0]===type)[1],variant:type==='knn'?'lab':source.variant};labMode=true;phase=2;Engine.init(current);if(type==='knn'){Engine.s.train=[];Engine.s.message='先选类别，再点画布添加点。你可以创造自己的数据分布。'}renderLesson();window.scrollTo(0,0)}
function openLevel(id){stopAnimation();current=LEVELS.find(l=>l.id===id);labMode=false;phase=0;decision=null;Engine.init(current);renderLesson();window.scrollTo(0,0)}
function renderLesson(){stopAnimation();let l=current;const labels=['先做决策','观察与发现','修改与训练','挑战新数据'];shell(`<div class="lessonhead"><button class="back" aria-label="返回" onclick="navigate('${labMode?'lab':'home'}')">←</button><div><div class="eyebrow" style="margin:0">${labMode?'自由实验室 · 自由探索':'CHAPTER '+CHAPTERS[l.chapter][0]+' / LEVEL '+String(l.id).padStart(2,'0')}</div><h2>${esc(l.title)}</h2></div></div>${labMode?'':`<div class="steps">${labels.map((x,i)=>`<span class="${i<=phase?'on':''}">${i+1} ${x}</span>`).join('')}</div>`}<div class="mission">${labMode?'自由改变数据与参数，观察结果。完成后保存作品。':phase===0?l.question:phase===1?'观察当前的 AI。哪里失败了？试着解释你看到的行为。':l.goal}</div>${phase===0&&!labMode?`<section class="card"><div class="row"><div style="width:85px;flex-shrink:0">${robot}</div><p style="margin:0">${l.desc}<br><small>先说说你的直觉，之后用实验检验。</small></p></div><div class="choices">${l.options.map((o,i)=>`<button class="choice ${decision===i?'selected':''}" onclick="choose(${i})">${String.fromCharCode(65+i)}. ${o}</button>`).join('')}</div>${decision!==null?`<div class="feedback">${decision===l.answer?'这是一个合理的起点。接下来看看实际表现。':'把这个想法带进实验，看看实际结果是否支持它。'}</div>`:''}</section>`:`<div class="playlayout"><section class="world">${Engine.html()}</section><aside class="brain"><h3>✳ 看看 AI 怎么判断</h3><div id="brain-visual"></div><code id="brain-content"></code><hr style="border:0;border-top:1px solid #d6dfc7;margin:20px 0"><p>输入 → 计算 → 输出<br>每次修改都会影响这里的结果。</p><button class="secondary wide" onclick="showWhy()">为什么会这样？</button></aside></div><div class="tabs"><button class="mobilebrain" onclick="showBrain()">✳ 看看 AI 怎么判断</button><button onclick="showWhy()">🔬 为什么？</button><button onclick="showCode()">⌘ 查看代码</button><button onclick="saveProject()">保存作品</button></div>`}<div class="lessonbottom">${labMode?'<button class="secondary" onclick="resetExperiment()">重置实验</button><button class="primary" onclick="saveProject()">保存实验项目 ↗</button>':phase===0?`<button class="primary" ${decision===null?'disabled':''} onclick="nextPhase()">看看 AI 怎么做 →</button>`:phase===1?'<button class="primary" onclick="discover()">发现问题，学习原理 →</button>':phase===2?'<button class="secondary" onclick="resetExperiment()">重新尝试</button><button class="primary" onclick="challenge()">挑战新数据 ↗</button>':'<button class="secondary" onclick="backToTrain()">返回改进</button><button class="primary" onclick="challenge()">再次测试 ↗</button>'}</div>`,labMode?'lab':'home');if(phase>0||labMode){Engine.draw();let c=$('#canvas');if(c)c.addEventListener('pointerdown',e=>{let b=c.getBoundingClientRect();Engine.click((e.clientX-b.left)*520/b.width,(e.clientY-b.top)*320/b.height)})}}
function choose(i){decision=i;renderLesson()}function nextPhase(){phase=1;renderLesson()}function backToTrain(){phase=2;renderLesson()}
function modal(title,html){$('#modal').classList.toggle('exo-diary-modal',html.includes('class="field-diary"'));$('#modal').classList.toggle('exo-terminal',html.includes('class="exo-shell"'));$('#modal').setAttribute('aria-label',title);$('#modal').innerHTML=`<div class="modalhead"><h2>${title}</h2><button aria-label="关闭对话框" onclick="closeModal()">✕</button></div>${html}`;$('#modal').showModal()}
function closeModal(){$('#modal').close()}
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){let b=e.target.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)closeModal()}});
function showWhy(){modal('为什么会这样？',`<div class="explain"><p>${current.why}</p><div class="feedback"><strong>试一个小实验</strong><p style="margin-bottom:0">一次只改变一个设置，记录预测或误差是否改变。然后问：改变来自数据、模型，还是训练方式？</p></div></div>`)}
function showCode(){modal('把直觉写成代码',`<div class="explain"><p>以下是本关核心逻辑的教学代码片段，不是可直接运行的完整程序。</p><pre>${esc(current.code)}</pre><p>网页中的实验使用 JavaScript 在本地实际计算。网络训练采用真实参数更新，KNN 则存储样本并计算距离。</p></div>`)}
function showBrain(){modal('✳ 看看 AI 怎么判断',`${brainVisual()}<pre style="white-space:pre-wrap;line-height:2;font-size:13px">${esc(Engine.brain())}</pre>`)}
function discover(){phase=2;renderLesson();showWhy()}
function setParam(k,v){stopAnimation();Engine.set(k,v);let el=document.getElementById('val-'+k);if(el)el.textContent=v}
function act(a){stopAnimation();Engine.action(a);$('#controls').innerHTML=Engine.controls();Engine.draw();let s=Engine.s;if(a==='route'&&s.type==='rl'){let path=[...s.path],msg=s.message,i=1;s.path=[path[0]];s.message='正在执行当前策略…';Engine.draw();animationTimer=setInterval(()=>{s.path=path.slice(0,++i);if(i>=path.length){stopAnimation();s.message=msg}Engine.draw()},170)}else if(a==='route'&&s.type==='agent'){let route=[...s.route],msg=s.message,i=0;s.state=0;s.log=[];Engine.draw();animationTimer=setInterval(()=>{let a=route[i++];s.log.push(['打开文件','整理内容','保存文件','关闭窗口'][a]);s.state=a===s.state?s.state+1:0;if(i>=route.length){stopAnimation();s.message=msg}Engine.draw()},550)}}
function tile(i){stopAnimation();Engine.tile(i)}
function challenge(){phase=3;renderLesson();let r=Engine.test();if(r.pass){progress[current.id]={date:new Date().toISOString(),result:r.detail};persist('academy-progress-v1',progress);modal('挑战完成！',`<div class="successrobot">${robot}</div><div class="resulttitle">你的 AI 又进步了。</div><p>${esc(r.detail)}</p><div class="feedback">你解锁的发现：${current.why}</div><div class="row" style="margin-top:20px"><button class="secondary" onclick="closeModal();saveProject()">保存作品</button><button class="primary" onclick="closeModal();${current.id<30?'openLevel('+(current.id+1)+')':"navigate('lab')"}">${current.id<30?'前往下一关 →':'进入自由实验室 ↗'}</button></div>`)}else{modal('还差一点，继续实验',`<p>${esc(r.detail)}</p><div class="feedback">${current.goal}<br>${hint()}</div><button class="primary wide" style="margin-top:20px" onclick="closeModal();backToTrain()">带着线索再试一次 →</button>`)}}
function hint(){let s=Engine.s;return ({rules:'试着把阈值放在两簇样本之间。',knn:s.v==='dirty'?'点击颜色与周围不同的样本，核实并修改标签。':s.v==='balance'?'补充橘子样本，再比较两类表现。':'检查特征和 K；在数据实验室还需亲自添加至少两个点。',reg:s.v==='overfit'?'选择直线模型，再点击训练。':'可以先试 w = 0.68、b = 0.16；自动训练时试学习率 0.2。',tree:'试试把 x、y 的阈值都放在 0.5 附近。',nn:'非线性数据可以试 8 个隐藏节点、学习率 0.08，再训练几次。',conv:'竖直边缘看左右差异；水平边缘看上下差异。',vision:'先保存 A 竖线、B 横线；开启增强后重新训练。流程关还要重新画图再识别。',rl:'试试终点奖励 10、探索率 0.3，训练后测试；封死道路会导致无法到达。',agent:'先点击学习，再运行智能体。',go:'先训练，再执黑落一子。'})[s.type]}
function resetExperiment(){Engine.init(current);if(labMode&&current.engine==='knn')Engine.s.train=[];renderLesson()}
function saveProject(){modal('保存我的 AI 作品',`<label>作品名称<input id="project-name" maxlength="60" value="${esc(current.title)} · ${projects.length+1}" style="width:100%;padding:12px;margin:12px 0;border:1px solid #ccd4c3;border-radius:10px"></label><p class="muted">保存数据、模型参数和当前实验设置到此浏览器。可在自由实验室导出 JSON 备份。</p><button class="primary wide" onclick="commitProject()">保存作品</button>`)}
function commitProject(){Engine.s.saved=true;let p={name:$('#project-name').value.trim()||current.title,date:new Date().toLocaleDateString('zh-CN'),engine:current.engine,level:{...current},state:Engine.export()};let updated=[p,...projects].slice(0,30);if(persist('academy-projects-v1',updated)){projects=updated;closeModal();toast('作品已保存，可在自由实验室继续实验或导出。')}}
function loadProject(i){let p=projects[i];current={...p.level,id:0,title:p.name};labMode=true;phase=2;Engine.init(current,p.state);renderLesson();window.scrollTo(0,0)}
function exportProject(i){let blob=new Blob([JSON.stringify({format:'ai-academy-v1',project:projects[i]},null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='ai-academy-project.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function importProject(){let el=document.createElement('input');el.type='file';el.accept='.json';el.onchange=async()=>{try{let f=el.files[0];if(!f)return;if(f.size>2e6)throw Error();let d=JSON.parse(await f.text()),p=d.project;if(!safeProjectValue(p?.state)||d.format!=='ai-academy-v1'||!p||!LABS.some(a=>a[0]===p.engine)||p.level?.engine!==p.engine||p.state?.type!==p.engine||typeof p.name!=='string')throw Error();let source=LEVELS.find(l=>l.engine===p.engine);p.level={...source,id:0,title:p.name};p.date=new Date().toLocaleDateString('zh-CN');let updated=[p,...projects].slice(0,30);if(persist('academy-projects-v1',updated)){projects=updated;lab();toast('项目已导入。')}}catch{toast('无法导入，请选择本网站导出的有效项目 JSON。')}};el.click()}
function inventory(){let abilities=[['发现规律',0,'特征与分类'],['预测未来',1,'回归与泛化'],['学习能力',2,'参数与神经网络'],['视觉能力',3,'像素与卷积'],['决策能力',4,'奖励与策略'],['创造能力',5,'自己的 AI 项目']];shell(`<div class="pagehead"><div class="eyebrow">YOUR ROBOT, YOUR JOURNEY</div><h1>每次实验，都留下成长。</h1><p>能力来自你完成的挑战。可以随时重玩任意关卡，重新检验自己的理解。</p></div><div class="hero"><div class="herotext"><h2>训练伙伴 · 小芽</h2><p>已完成 <strong>${count()} / 30</strong> 项挑战<br>已保存 <strong>${projects.length}</strong> 个 AI 作品</p><div class="progress"><span style="width:${count()/30*100}%"></span></div><p style="margin-top:15px">${count()?'继续探索，让它获得下一项能力。':'它正在等待你的第一条指令。'}</p></div><div class="robot-stage">${robot}</div></div><div class="sectionhead"><h2>能力图鉴</h2><small>每章 5 关完成后解锁</small></div><div class="inventory">${abilities.map(([name,ch,desc])=>{let n=LEVELS.filter(l=>l.chapter===ch&&progress[l.id]).length;return `<div class="card ${n===5?'complete':''}"><div class="iconbox">${n===5?'✓':CHAPTERS[ch][3]}</div><h3 style="margin-top:15px">${name}</h3><p class="muted">${desc}</p><div class="progress"><span style="width:${n*20}%"></span></div><small>${n}/5 ${n===5?'已解锁':'探索中'}</small></div>`}).join('')}</div><div class="sectionhead"><h2>已经完成的挑战</h2></div>${count()?LEVELS.filter(l=>progress[l.id]).map(l=>`<button class="card wide row between" style="margin-bottom:8px" onclick="openLevel(${l.id})"><span>✓ ${l.id}. ${esc(l.title)}</span><small>重玩 ↗</small></button>`).join(''):'<p class="muted">从冒险地图开始，记录你的第一次发现。</p>'}`,'robot')}

function brainVisual(){let s=Engine.s;if(!s||s.type!=='nn')return '';let h=s.hidden,ys=n=>Array.from({length:n},(_,i)=>20+(i+1)*150/(n+1)),ins=ys(2),middle=ys(h),out=95;let paths='';if(h){for(let j=0;j<h;j++){for(let i=0;i<2;i++){let w=s.net.a[j][i];paths+=`<line x1="20" y1="${ins[i]}" x2="100" y2="${middle[j]}" stroke="${w<0?'#df986b':'#6a9360'}" stroke-width="${Math.min(4,.5+Math.abs(w))}"/>`}paths+=`<line x1="100" y1="${middle[j]}" x2="180" y2="${out}" stroke="${s.net.b[j]<0?'#df986b':'#6a9360'}" stroke-width="${Math.min(4,.5+Math.abs(s.net.b[j]))}"/>`}}else paths=ins.map((y,i)=>`<line x1="20" y1="${y}" x2="180" y2="${out}" stroke="${s.net.linear[i]<0?'#df986b':'#6a9360'}" stroke-width="${Math.min(4,.5+Math.abs(s.net.linear[i]))}"/>`).join('');let circles=ins.map(y=>`<circle cx="20" cy="${y}" r="7"/>`).join('')+middle.map(y=>`<circle cx="100" cy="${y}" r="5"/>`).join('')+`<circle cx="180" cy="95" r="8"/>`;return `<svg viewBox="0 0 200 185" role="img" aria-label="网络连接：绿色为正权重，橙色为负权重，粗细表示绝对值">${paths}<g fill="#f5f8eb" stroke="#416b4b" stroke-width="2">${circles}</g></svg><small>绿色正权重 · 橙色负权重<br>粗细表示权重绝对值</small>`}
const originalDraw=Engine.draw.bind(Engine);Engine.draw=function(){originalDraw();let el=document.getElementById('brain-visual');if(el)el.innerHTML=brainVisual()};

function safeProjectValue(value,depth=0){if(depth>8)return false;if(value===null||typeof value==='boolean')return true;if(typeof value==='number')return Number.isFinite(value);if(typeof value==='string')return value.length<5000&&!/[<>&]/.test(value);if(Array.isArray(value))return value.length<=20000&&value.every(x=>safeProjectValue(x,depth+1));if(typeof value==='object')return Object.entries(value).every(([k,v])=>!['__proto__','constructor','prototype'].includes(k)&&safeProjectValue(v,depth+1));return false}
